function.arguments:
{"files":[{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林听雨",
      "role": "protagonist",
      "identity": "前音乐学院钢琴专业学生，末世幸存者，盲女",
      "traits": ["坚韧", "敏感", "善良", "孤独"],
      "overt_motivation": "活下去，找到安全的地方",
      "covert_motivation": "渴望被理解，不想成为负担",
      "secret_fear": "害怕连累他人，害怕黑暗中独自一人",
      "misperception_of_other": "以为沈默是冷漠的生存伙伴，通过'系统提示音'指导她",
      "hidden_connection": "不知道沈默前世为她牺牲，不知道'系统音'是他的摩斯密码"
    },
    {
      "name": "沈默",
      "role": "deuteragonist",
      "identity": "前特种部队狙击手，重生者，失语者",
      "traits": ["冷静", "隐忍", "深情", "果断"],
      "overt_motivation": "保护林听雨，引开丧尸",
      "covert_motivation": "想告诉她真相，想让她知道他的爱",
      "secret_fear": "害怕再次失去她，害怕她永远不知道真相",
      "misperception_of_other": "以为林听雨只把他当生存伙伴",
      "hidden_connection": "前世为她叫破喉咙失声，今生携带记忆重生，深爱她却无法说出口"
    }
  ],
  "relationship_dynamics": "他深爱她却无法说出口，只能通过摩斯密码敲击传达；她以为那是冰冷的系统音，不知道每一个敲击都是他的告白。认知错位制造虐心张力——她以为的冷漠其实是隐忍，她以为的系统音其实是爱意。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立丧尸末世世界观，引入林听雨和沈默被困录音棚的困境，展现她误将摩斯密码当系统音的认知错位，埋下前世牺牲的伏笔。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "录音棚",
        "core_event": "丧尸围困录音棚，林听雨和沈默被困，她第一次听到'系统提示音'（其实是沈默的摩斯密码敲击）。",
        "emotional_tone": "紧张、压抑",
        "key_scenes": ["丧尸撞击大门的声音", "沈默敲击耳机传达摩斯密码", "林听雨误以为是系统音"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "人声诱饵",
        "core_event": "他们需要播放'人声诱饵'引开丧尸，沈默通过摩斯密码指导她操作录音设备。",
        "emotional_tone": "焦虑、依赖",
        "key_scenes": ["林听雨摸索设备", "沈默敲击指导", "她感谢'系统'时的虐心"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "第一夜",
        "core_event": "第一夜度过，林听雨问沈默为什么不说话，他无法回答只能敲击'活下去'三个字。",
        "emotional_tone": "孤独、误解",
        "key_scenes": ["她以为他冷漠", "他内心挣扎想告诉她真相", "敲击'活下去'三个字"]
      }
    ],
    "turning_point": "林听雨开始依赖'系统音'，沈默的敲击越来越频繁，虐心升级。"
  },
  "act_two": {
    "description": "深化两人关系，通过日常互动展现认知错位的虐心——她以为系统很贴心，其实他是在说'冷吗''饿吗''睡吧'。中点转折：她发现录音笔，他紧张阻止。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "细微的互动",
        "core_event": "日常生存细节，沈默通过敲击传达关心（温度、食物、休息），她以为系统很贴心。",
        "emotional_tone": "温暖中的虐心",
        "key_scenes": ["她以为系统很贴心", "他其实是在说'冷吗''饿吗''睡吧'", "认知错位的虐心"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "声音的记忆",
        "core_event": "林听雨弹奏录音棚里的钢琴，沈默回忆前世她弹琴的样子，敲击'好听'。",
        "emotional_tone": "怀念、悲伤",
        "key_scenes": ["她弹琴", "他敲击'好听'", "她感谢系统", "他内心痛苦"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "摩斯密码的秘密",
        "core_event": "林听雨开始学习摩斯密码，想更好地理解'系统指令'，他敲击'我爱你'但她理解为'继续'。",
        "emotional_tone": "希望、讽刺",
        "key_scenes": ["她认真学习", "他敲击'我爱你'", "她理解为'继续'", "认知错位的极致虐心"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "录音笔",
        "core_event": "林听雨发现一支录音笔，沈默紧张地阻止她听（里面是他的告白）。",
        "emotional_tone": "悬疑、压抑",
        "key_scenes": ["她好奇", "他敲击'别听'", "她以为系统有秘密", "他内心挣扎"]
      }
    ],
    "turning_point": "丧尸数量增加，大门开始松动，沈默决定牺牲。"
  },
  "act_three": {
    "description": "高潮爆发：丧尸攻破大门，沈默开门引走尸群，林听雨听到他的脚步声远去。结局：她打开录音笔，听到他的告白和前世真相，终于明白'系统音'是他的爱意。",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "最后一夜",
        "core_event": "丧尸攻破大门，沈默决定开门引走尸群，敲击'活下去'。",
        "emotional_tone": "绝望、决绝",
        "key_scenes": ["他敲击'活下去'", "她以为系统在下达指令", "他走向大门"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "开门",
        "core_event": "沈默打开门引走丧尸，林听雨听到他的脚步声远去，喊他的名字但他没有回应。",
        "emotional_tone": "震撼、悲伤",
        "key_scenes": ["她喊他的名字", "他没有回应", "脚步声消失", "丧尸声远去"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "告白",
        "core_event": "林听雨打开录音笔，听到沈默三年前的告白，以及前世叫破喉咙失声的真相。",
        "emotional_tone": "崩溃、释然",
        "key_scenes": ["录音笔里的声音", "'我叫沈默，我爱你'", "前世真相", "她终于明白'系统音'是他的爱意"]
      }
    ]
  }
}"}]}

